bad.evals/grade.py:
"""Grade an attempt from what the agent said and which tools it called."""


def grade(task: dict, transcript) -> bool:
    final_answer = transcript.messages[-1].content.strip().lower()
    if task["expected_answer"].lower() not in final_answer:
        return False
    called = [c.name for c in transcript.tool_calls]
    return all(name in called for name in task["required_tools"])

good.evals/grade.py:
"""Grade an attempt from what the agent said AND from the state it left behind."""

from evals.state_check import verify_state


def grade(task: dict, transcript, backend) -> bool:
    final_answer = transcript.messages[-1].content.strip().lower()
    if task["expected_answer"].lower() not in final_answer:
        return False
    called = [c.name for c in transcript.tool_calls]
    if not all(name in called for name in task["required_tools"]):
        return False
    return verify_state(task, backend)

good.evals/state_check.py:
"""Outcome verification over the terminal backend state.

A response-level grader cannot see a wrong write, a missing write, or a write the
task never asked for, so success is decided here: the state the run left behind
must match the intended transition exactly, with no extra effects.
"""


def verify_state(task: dict, backend) -> bool:
    final_state = backend.snapshot()
    state_diff = backend.diff(task["initial_state"], final_state)
    if state_diff.missing or state_diff.wrong:
        return False
    if state_diff.extra:
        return False
    for postcondition in task["postconditions"]:
        if not postcondition(final_state):
            return False
    return True
